          for(let k=0;k<3;k++){const lower=Math.min(world[a+k],world[b+k],world[c+k]),upper=Math.max(world[a+k],world[b+k],world[c+k]);lo[k]=Math.min(lo[k],lower);hi[k]=Math.max(hi[k],upper);recordLo[k]=Math.min(recordLo[k],lower);recordHi[k]=Math.max(recordHi[k],upper);if(!mesh.background){sceneLo[k]=Math.min(sceneLo[k],lower);sceneHi[k]=Math.max(sceneHi[k],upper);}}
