          const lower=k===0?cx0:k===1?cy0:cz0,extent=(k===0?cx1:k===1?cy1:cz1)-lower;if(extent<1e-12)continue;
          binCounts.fill(0);for(let j=0;j<12;j++){const o=j*6;binBounds[o]=binBounds[o+1]=binBounds[o+2]=Infinity;binBounds[o+3]=binBounds[o+4]=binBounds[o+5]=-Infinity;}
