    const body=fastenerCircleDescriptor(d.body/2,4),head=fastenerCircleDescriptor(d.head/2,4),inner=fastenerCircleDescriptor(d.d/2,4,true);
     
    const csk=kind==='rivet_csk',height=csk?d.L:d.L+d.K,bodyTop=height-d.K;
