function nutSizeOptions(kind){if(kind==='rivet')return Object.keys(FASTENER_RIVET);if(kind==='rivet_csk')return Object.keys(FASTENER_RIVET_CSK);if(kind==='high')return Object.keys(FASTENER_NUT_HIGH);if(kind==='flange')return Object.keys(FASTENER_NUT_FLANGE);if(kind==='nyloc')return Object.keys(FASTENER_NUT_NYLOC);if(kind==='insert')return Object.keys(FASTENER_NUT_INSERT);if(kind==='tslide')return Object.keys(FASTENER_TSLOT_SLIDE);if(kind==='tswivel')return Object.keys(FASTENER_TSLOT_SWIVEL);return Object.keys(FASTENER_NUT_HEX);}
