    if(libraryBatchCache.size>128)for(const [key,b] of libraryBatchCache)if(!b.used){b.mesh.dispose();b.mesh.geometry.dispose();b.mesh.removeFromParent();if(b.wire){b.wire.geometry.dispose();b.wire.material.dispose();b.wire.removeFromParent();}libraryBatchCache.delete(key);}
