  for(let i=0;i<p.count;i++)positions.set([p.getX(i),p.getY(i),p.getZ(i)],i*3);
  const url=URL.createObjectURL(new Blob(['const recognize=(',createEngineeringRecognition.toString(),')().recognize;onmessage=e=>{try{postMessage({result:recognize(e.data.positions,e.data.indices,e.data.options)})}catch(error){postMessage({error:error.message||String(error)})}}'],{type:'text/javascript'}));
