          const edges=refs.map(r=>{const cp=segmentPoints(data,r.edge);return r.reversed?cp.reverse():cp;}),prepared=SurfaceBuilder.prepare({edges,angleMax:Math.max(1,+data.approximation.angle||10),preview:true}),a=g.attributes.position.array;
