function frameMorphTube(data, centers, radii, options = {}) {
  const rings = [],
    all = [],
    axis = FrameMorph.unit(FrameMorph.sub(centers.at(-1), centers[0])),
    u = FrameMorph.unit(
      FrameMorph.cross(axis, Math.abs(axis[2]) < 0.9 ? [0, 0, 1] : [0, 1, 0]),
    ),
    v = FrameMorph.cross(axis, u),
    edge = (a, b, ha = [0, 0, 0], hb = [0, 0, 0]) => {
      const q = addSplineSequence(data);
      return addSplineSegment(data, q, a, b, ha, hb);
    };
  for (let j = 0; j < centers.length; j++) {
    const r = radii[j] || radii.at(-1),
      ring = [];
    for (let i = 0; i < 4; i++) {
      const angle = ((i + 0.5) * Math.PI) / 2,
        p = FrameMorph.add(
          centers[j],
          FrameMorph.add(
            FrameMorph.mul(u, Math.cos(angle) * r[0]),
            FrameMorph.mul(v, Math.sin(angle) * r[1]),
          ),
        );
      ring.push(addSplineVertex(data, p));
    }
    for (let i = 0; i < 4; i++) {
      const a = ((i + 0.5) * Math.PI) / 2,
        b = ((i + 1.5) * Math.PI) / 2,
        k = options.square ? 0 : 0.55228475;
      edge(
        ring[i],
        ring[(i + 1) % 4],
        FrameMorph.add(
          FrameMorph.mul(u, -Math.sin(a) * r[0] * k),
          FrameMorph.mul(v, Math.cos(a) * r[1] * k),
        ),
        FrameMorph.add(
          FrameMorph.mul(u, Math.sin(b) * r[0] * k),
          FrameMorph.mul(v, -Math.cos(b) * r[1] * k),
        ),
      );
      if (j) edge(rings[j - 1][i], ring[i]);
    }
    rings.push(ring);
    all.push(...ring);
  }
  return { rings, vertices: all };
}
function frameMorphLink(data, a, b) {
  const q = addSplineSequence(data);
  return addSplineSegment(data, q, a, b);
}
