async function frameCreateMorphLever(options = {}) {
  const data = createSplineData({ angle: 25 }),
    a = frameMorphTube(
      data,
      [
        [0, 0, 0],
        [300, 0, 0],
        [305, 0, 0],
      ],
      [
        [15, 20],
        [15, 20],
        [15, 20],
      ],
      { square: true },
    ),
    b = frameMorphTube(
      data,
      [
        [300, 0, 0],
        [550, 0, 0],
      ],
      [
        [14, 18],
        [14, 18],
      ],
      { square: true },
    );
  frameMorphLink(data, a.rings[1][0], b.rings[0][0]);
  const cmd = cmdAddSplineObject(data, options.name || "Lever · 300 + 250 mm", {
    enterDrawing: false,
  });
  runCmd(cmd);
  const cage = [...selNodes][0];
  frameMorphCreate(cage, { undo: false, select: false });
  const controls = [];
  for (const [name, vertices, center, angle, min, max] of [
    ["Drive", [...a.vertices, ...b.vertices], [0, 0, 0], 90, -1, 1],
    ["Coupler", b.vertices, [300, 0, 0], 150, -1, 1],
  ]) {
    const m = frameMorphAdd(cage, name, { min, max, undo: false }).morph;
    frameMorphKey(cage, m, 1, {
      vertices,
      center,
      axis: [0, 0, 1],
      angle,
      undo: false,
    });
    frameMorphKey(cage, m, min, {
      vertices,
      center,
      axis: [0, 0, 1],
      angle: angle * min,
      undo: false,
    });
    frameMorphFind(frameMorphTag(cage), m).value = 0;
    controls.push(m);
  }
  const tag = frameMorphTag(cage);
  tag.enable = true;
  frameMorphApply(cage);
  const patch = await window.frameAI.createSplineGenerator("spline_patch", [
    cage,
  ]);
  const object = patch.object || patch;
  OBJ.get(object).name = options.name || "Lever · 300 + 250 mm";
  tag.fixture = {
    kind: "lever",
    lengths: [300, 250],
    unit: "mm",
    tip: b.rings.at(-1),
    controls,
  };
  await window.frameAI.waitForIdle();
  frameMorphSelect(cage);
  return {
    object,
    cage,
    controls,
    tip: b.rings.at(-1),
    lengths: [300, 250],
    unit: "mm",
  };
}
function frameMorphDemoAPI(api) {
  api.createMorphHuman = frameCreateMorphHuman;
  api.createMorphLever = frameCreateMorphLever;
  const help = api.help;
  api.help = (name) => {
    const out = help(name),
      docs = {
        createMorphHuman:
          "({height?:1750,name?}) -> editable SplinePatch engineering figure; millimetres, 36 scalar controls, separate curl/spread for all ten fingers",
        createMorphLever:
          "({name?}) -> editable 300 + 250 mm lever with bounded Morph IK",
      };
    if (name && docs[name]) out.signature = docs[name];
    else if (!name) Object.assign(out.methods, docs);
    return out;
  };
}

 

